
CREATE TABLE atributo_sinonimos (
    id                  UUID PRIMARY KEY,
    atributo_id         UUID NOT NULL,
    termo               VARCHAR(120) NOT NULL UNIQUE,
    CONSTRAINT fk_atributo_sinonimos_atributo
        FOREIGN KEY (atributo_id) REFERENCES atributos_definicao(id) ON DELETE CASCADE
);
CREATE INDEX ix_atributo_sinonimos_atributo ON atributo_sinonimos(atributo_id);





































